head.script:
scwin.onpageload = function() {
    scwin.makeDcObj();
    scwin.makeDcObj2();
};
scwin.onpageunload = function() {};
scwin.makeDcObj = function() {
    try {
        //$p.data.remove( "dtm_test" ); 
        var infoArr = ['col1', 'col2'];
        var option = {
            "type": "dataMap",
            "option": {
                "baseNode": "list",
                "repeatNode": "map"
            },
            "keyInfo": []
        };
        for (var idx in infoArr) {
            option.keyInfo.push({
                "id": infoArr[idx],
                "name": infoArr[idx]
            });
        }
        option.id = "dtm_test";
        $p.data.create(option);
        var dataMapObj = $p.getComponentById(option.id);
        dataMapObj.setJSON({
            'col1': '123',
            col2: '234'
        });
        txa_data.setValue(JSON.stringify(dataMapObj.getJSON(), null, 3));
    } catch (e) {
        txa_data.setValue(e);
    }
};
scwin.makeDcObj2 = function() {
    try {
        //$p.data.remove( "dtl_test" ); 
        var infoArr = ['col1', 'col2', 'col3'];
        var option = {
            "type": "linkedDataList",
            "option": {
                "baseNode": "list",
                "repeatNode": "map",
                "bind": "dataList1"
            },
            "columnInfo": []
        };
        for (var idx in infoArr) {
            option.columnInfo.push({
                "id": infoArr[idx]
            });
        }
        option.id = "ldtl_test";
        $p.data.create(option);
        var dataListObj = $p.getComponentById(option.id);
        //dataListObj.setJSON([{col1:'123',col2:'234',col3:'345'},{col1:'123',col2:'234',col3:'345'},{col1:'123',col2:'234',col3:'345'}]);
        textarea1.setValue(JSON.stringify(dataListObj.getAllJSON(), null, 3));
    } catch (e) {
        textarea1.setValue(e);
    }
};
scwin.trigger1_onclick = function(e) {
    scwin.makeDcObj();
};
scwin.trigger2_onclick = function(e) {
    scwin.makeDcObj2();
};
